/// Convert a raw parse tree (a `List` of `RawStmt`) into the AST's
/// statements; NULL is empty.
///
/// # Safety
/// `list` must be NULL or point to a valid `List` of `RawStmt`.
pub(crate) unsafe fn raw_stmts(list: *const bindings::List) -> ::std::vec::Vec<protobuf::RawStmt> {
    begin();
    let mut out = ::std::vec::Vec::new();
    if list.is_null() {
        return out;
    }
    let list = unsafe { &*list };
    let length = list.length.max(0) as usize;
    out.reserve(length);
    for index in 0..length {
        let cell = unsafe { &*list.elements.add(index) };
        out.push(unsafe { raw_stmt(cell.ptr_value as *const bindings::RawStmt) });
    }
    out
}

